function CardList({items}:{items:[string,string][]}){return <view className="demo-card-list">{items.map(([title,description])=><view className="demo-card-list-item" key={title}><image className="demo-card-list-image" src={cat} mode="aspectFill"/><view className="demo-card-list-copy"><text className="demo-card-list-title">{title}</text><text className="demo-card-description">{description}</text></view></view>)}</view>;}
function CardTitle({title,tip,icon}:{title:string;tip:string;icon:string}){return <view className="demo-card-custom-title"><text>{title}</text><view className="demo-card-title-tip"><Icon name={icon} size={14} color="#868a9c"/><text>{tip}</text></view></view>;}
export function CardExample(){
  const toast=useToast(),dialog=useDialog();
  const actions=(labels:string[]):ReactNode=><view className="demo-card-actions">{labels.map(label=><Button key={label} size="small" variant="plain" label={label} onTap={()=>{ 'background only'; if(label==='阅读全文')void dialog.alert({title:'岳阳楼记',msg:passage});else toast.success(`${label}成功`); }}/>)}</view>;
  return <view className="demo-card-page">
    <DemoGroup title="组件类型"><ExampleBlock noPadding title="基本使用">
      <Card variant="standard" title="岳阳楼记" footer={actions(['阅读全文'])}><text className="demo-card-passage">{passage}</text></Card>
      <Card variant="standard" title="个人名片" footer={actions(['关注'])}><view className="demo-card-user"><image className="demo-card-user-image" src={cat} mode="aspectFill"/><view className="demo-card-user-copy"><text className="demo-card-user-title">小黑猫的故事</text><text className="demo-card-description">一只温柔的黑色小猫，喜欢在午后的阳光下打滚，追逐蝴蝶。</text><text className="demo-card-meta">粉丝 12.5w</text></view></view></Card>
    </ExampleBlock><ExampleBlock noPadding title="矩形卡片"><Card type="rectangle" title="生活记录" footer={actions(['点赞','评论'])}><CardList items={[["今天天气真好","2026年2月11日 晴天 22℃"],["慵懒的午睡时光","阳光洒进房间，舒服得不想动"]]}/></Card></ExampleBlock></DemoGroup>
    <DemoGroup title="组件样式"><ExampleBlock noPadding title="复杂卡片"><Card variant="standard" title="宠物档案" footer={actions(['点赞 (1.2w)','收藏','分享'])}><view className="demo-card-info"><view className="demo-card-info-image-box"><image className="demo-card-info-image" src={cat} mode="aspectFill"/><text className="demo-card-info-badge">人气之星</text></view><view className="demo-card-info-copy"><text className="demo-card-info-title">小黑：治愈系黑色小猫咪</text><view className="demo-card-info-meta"><text className="demo-card-info-tag">萌宠日常</text><text className="demo-card-info-time">2小时前发布</text></view><view className="demo-card-props">{[[['品种','中华田园猫'],['性格','活泼好动'],['特技','高能跳跃']],[['年龄','0.5岁'],['性别','女'],['坐标','上海']]].map((column,index)=><view key={index} className="demo-card-prop-col">{column.map(([label,value])=><view key={label} className="demo-card-prop"><text className="demo-card-prop-label">{label}</text><text className="demo-card-prop-value">{value}</text></view>)}</view>)}</view></view></view></Card></ExampleBlock></DemoGroup>
    <DemoGroup title="内容形态"><ExampleBlock noPadding title="自定义标题"><Card type="rectangle" title={<CardTitle title="兴趣爱好" tip="快乐源泉" icon="heart"/>} footer={actions(['点赞','分享'])}><CardList items={[["窗边的午睡","最喜欢在温暖的阳光下打盹"],["毛线球游戏","追逐毛线球时最专注最可爱"]]}/></Card></ExampleBlock></DemoGroup>
    <DemoGroup title="特殊样式"><ExampleBlock noPadding title="去除 Footer"><Card type="rectangle" title="精彩瞬间"><view className="demo-card-moment"><image className="demo-card-user-image" src={cat} mode="aspectFill"/><view className="demo-card-moment-copy"><text className="demo-card-moment-title">午后阳光下的惬意时光</text><text className="demo-card-description">今天的天气真好，阳光洒在身上暖洋洋的。小黑在窗台上睡得正香，偶尔动动耳朵，大概是梦见了好吃的鱼罐头吧。</text><text className="demo-card-meta">阅读 3.5w</text></view></view></Card><Card type="rectangle" title={<CardTitle title="更多动态" tip="每日更新" icon="warning"/>}><CardList items={[["翻肚皮打滚特技","超级可爱的示范表演，萌化你的心"],["高空跳跃绝技","展现猫咪的灵活身手，惊叹连连"]]}/></Card></ExampleBlock></DemoGroup>
    <Dialog {...dialog.props}/><Toast {...toast.props}/>
  </view>;
}

