function Standalone({custom=false,half=false}:{custom?:boolean;half?:boolean}){const[value,setValue]=useState<ChoiceValue>(custom?'yes':false),[indeterminate,setIndeterminate]=useState(half);return <Checkbox value={value} trueValue={custom?'yes':true} falseValue={custom?'no':false} indeterminate={indeterminate} onChange={({value})=>{'background only';setValue(value);setIndeterminate(false);}}>{half?'半选状态':'多选 1'}</Checkbox>;}
