ap((label,i)=><Cell key={label} title={label} clickable center onTap={()=>toggle(i+1)}><Checkbox name={i+1}/></Cell>)}</CellGroup></CheckboxGroup></ExampleBlock><ExampleBlock title="全选切换"><view className="demo-checkbox-actions">{([{label:'全部切换',tone:'neutral',action:undefined},{label:'全选',tone:'success',action:true},{label:'全不选',tone:'primary',action:false},{label:'全部切换跳过禁用',tone:'warning',action:{skipDisabled:true}},{label:'全部选中跳过禁用',tone:'danger',action:{checked:true,skipDisabled:true}}] as const).map(item=><Button size="small" key={item.label} label={item.label} tone={item.tone} onTap={()=>ref.current?.toggleAll(item.action)}/>)}</view><CheckboxGroup ref={ref} value={all} onChange={({value})=>setAll(value)} className="demo-choice-group">{[1,2,3,4].map(name=><Checkbox key={name} name={name} disabled={name===3}>{`多选 ${name}${name===3?'(Disabled)':''}`}</Checkbox>)}</CheckboxGroup></ExampleBlock></DemoGroup></view>;}

