  }}
/>
<FormRadioRow
  label="选项"
  value={choice}
  options={[
    { value: 'a', label: '选项 A' },
    { value: 'b', label: '选项 B' },
  ]}
  onChange={(value) => {
    'background only';
    setChoice(value);
  }}
/>
<FormTextareaRow
  label="备注"
  value={note}
  maxlength={200}
  maxlines={4}
  onInput={(value) => {
    'background only';
    setNote(value);
  }}
  last
/>
```

