  const height=index===1?200:index===2||index===3?168.75:200,result=images[index];
  return <view className={`demo-cropper-preview ${index===0||index===4?'demo-cropper-circular':'demo-cropper-rectangular'}`} style={{height:`${height}px`}} bindtap={()=>open(index)} accessibility-element accessibility-label="选择裁剪图片" accessibility-traits="button">
