  const [multiple, setMultiple] = useState<PickerValue[]>(['中南大学', '软件工程']), [area, setArea] = useState<PickerValue[]>(['110000', '110100', '110102']), [fields, setFields] = useState<PickerValue[]>([1]), [message, setMessage] = useState('');
