      <ExampleBlock title="多列" noPadding>{result('multiple')}<PickerView value={multiple} columns={pickerUniversity} onChange={({ value }) => { setMultiple(value); report('multiple', value); }} /></ExampleBlock>
      <ExampleBlock title="多级联动" noPadding>{result('area')}<PickerView value={area} columns={pickerAreas} cascade onChange={({ value }) => { setArea(value); report('area', value); }} /></ExampleBlock>
