import {RichTextMediaExample} from './rich-text-media.js';
import {useInitData,useRef,useState} from '@lynx-js/react';
import type {NodesRef} from '@lynx-js/types';
import { Button, ConfigProvider, RichText } from '@daisu-ui/ui';
import type { RichTextHeading, RichTextRef } from '@daisu-ui/ui';
import {DemoGroup,ExampleBlock} from './shared.js';
import {editorExamples,invitation,invitationStyles,journal,journalStyles,lake,letter,longJournal,originalLake} from './rich-text-content.js';
const articleStyle={p:'line-height:1.95;margin:0 0 16px;',th:'text-align:left;',td:'font-size:13px;'};
export function RichTextExample(){
 const init=useInitData() as unknown;
 const browser=!!init&&typeof init==='object'&&'browserMedia' in init&&init.browserMedia===true;
 const[content,setContent]=useState(letter),[messages,setMessages]=useState<Record<string,string>>({}),[dark,setDark]=useState(false),[editor,setEditor]=useState(0),[expanded,setExpanded]=useState(false),[headings,setHeadings]=useState<RichTextHeading[]>([]);
 const article=useRef<RichTextRef>(null),scroll=useRef<NodesRef|null>(null),longSection=useRef<NodesRef|null>(null),top=useRef(0);
 const measure=(node:NodesRef)=>new Promise<{top:number}>((resolve,reject)=>node.invoke({method:'boundingClientRect',success:v=>resolve(v as {top:number}),fail:()=>reject(new Error('无法测量滚动位置'))}).exec());
 const scrollToRect=async(rect:{top:number},offset:number)=>{'background only';const node=scroll.current;if(!node)throw new Error('滚动容器已关闭');const bounds=await measure(node),next=Math.max(0,top.current+rect.top-bounds.top-offset);await new Promise<void>((resolve,reject)=>node.invoke({method:'scrollTo',params:{offset:next,index:0,smooth:false},success:()=>resolve(),fail:()=>reject(new Error('滚动失败'))}).exec());};
 const collapse=async()=>{'background only';const section=longSection.current;if(!section)return;try{const rect=await measure(section);setExpanded(false);setHeadings([]);await scrollToRect(rect,0);}catch{setExpanded(false);}};
 const feedback=(key:string,text:string)=>{'background only';setMessages(old=>({...old,[key]:text}));};
 const note=(key:string)=>messages[key]?<text className="demo-rich-feedback">{messages[key]}</text>:null;
 const jump=async(id:string)=>{'background only';try{await article.current!.scrollToAnchor(id,{offset:16,duration:0});}catch{feedback('anchor','章节位置已变化，请重新选择。');}};
 return <scroll-view ref={scroll} className="ui-demo-component-scroll" scroll-orientation="vertical" scroll-y bindscroll={e=>{'background only';top.current=e.detail.scrollTop;}}><view className="ui-demo-component-content demo-rich-page"><DemoGroup title="组件类型"><ExampleBlock title="基础图文 · 周末出走"><view className="demo-rich-article"><RichText content={journal} classStyles={journalStyles} tagStyle={articleStyle} selectable onLinkClick={()=>{'background only';feedback('article','行前准备：舒适的鞋、饮水、轻食和随身垃圾袋。');}}/></view>{note('article')}</ExampleBlock></DemoGroup>
 <DemoGroup title="组件状态"><ExampleBlock title="内容更新与空状态"><view className="demo-rich-actions"><Button size="small" label="更新来信" onTap={()=>{'background only';setContent('<p><strong>计划已更新</strong></p><p>出发时间改为周六上午九点。别忘了带上水和一件轻外套。</p>');}}/><Button size="small" label="清空内容" onTap={()=>{'background only';setContent('');}}/><Button size="small" label="恢复来信" onTap={()=>{'background only';setContent(letter);}}/></view><view className="demo-rich-dynamic"><RichText content={content}><text className="demo-rich-empty">还没有新的来信，去看看窗外吧。</text></RichText></view></ExampleBlock>
 <ExampleBlock title="图片加载失败与占位"><RichText content={'<img src="" alt="这张照片暂时无法加载" width="100%" height="80">'}/><text className="demo-rich-hint">照片暂不可用时，用自定义占位图承接。</text></ExampleBlock></DemoGroup>
 <DemoGroup title="组件变体"><ExampleBlock title="图片预览"><view className="demo-rich-photo"><RichText content={`<img src="${lake}" original-src="${originalLake}" alt="点击查看山湖大图" width="100%"><p class="journal-note">轻触照片，看看远处的山。</p>`} classStyles={journalStyles} onImageLoad={e=>{'background only';feedback('size',`照片尺寸：${e.width} × ${e.height}，轻触预览原图。`);}}/></view>{messages.size?<text className="demo-rich-hint">{messages.size}</text>:null}</ExampleBlock>
 <ExampleBlock title="链接点击"><RichText content={'<p>一次轻装出行，从一份简单的<a href="/journal/gear">行前准备清单</a>开始。沿途看到喜欢的风景，也记得<a href="/journal/share">分享给同行的人</a>。</p>'} onLinkClick={({href})=>{'background only';feedback('link',href==='/journal/gear'?'清单已打开：带上饮水和轻外套，轻装出发。':'这段旅途，值得分享给你在意的人。');}}/>{note('link')}</ExampleBlock>
