  return createRouter({
    routeTree: root.addChildren([page]),
    initial: '/example',
    toPath: (path) => path,
    fromMatch: (match) => ({ path: match.pathname }),
    stringify: (route) => route.path,
  });
});

<RouterView router={router} renderRoute={() => <RouteScreen />} />

