    <ExampleBlock title="分栏间隔"><Row gutter={20}>{[0, 1, 2].map(index => <Col key={index} span={8}><LayoutCell label="span: 8" tone={index % 2 ? 'light' : 'strong'} /></Col>)}</Row></ExampleBlock>
