import { useRef, useState } from '@lynx-js/react';
import { Button, Icon, Popup, Signature, Toast, useToast } from '@daisu-ui/ui';
import type { SignatureRef, SignatureResult } from '@daisu-ui/ui';
import { DemoGroup, ExampleBlock } from './shared.js';
export function SignatureExample({onOpen}:{onOpen:(page:'signature-landscape')=>void}){
  const [disabled,setDisabled]=useState(true),[show,setShow]=useState(false),[image,setImage]=useState(''),ref=useRef<SignatureRef>(null),toast=useToast();
  const confirm=(result:SignatureResult)=>{'background only';if(result.success){setShow(false);setImage(result.dataUrl);}else toast.show(result.error??'导出失败');};
  return <view className="demo-signature-page">
    <DemoGroup title="组件类型"><ExampleBlock title="基础用法"><Signature exportScale={2} backgroundColor="#ffffff" onConfirm={confirm}/></ExampleBlock><ExampleBlock title="历史记录"><Signature enableHistory backgroundColor="#f5f5f5" onConfirm={confirm}/></ExampleBlock></DemoGroup>
    <DemoGroup title="组件变体"><ExampleBlock title="笔锋模式-基础"><Signature pressure height={300} onConfirm={confirm}/></ExampleBlock><ExampleBlock title="笔锋模式-自定义"><Signature pressure height={300} minWidth={1} maxWidth={6} minSpeed={1.5} backgroundColor="#f5f5f5" onConfirm={confirm}/><text className="demo-signature-tip">快速书写产生细线条，慢速书写产生粗线条</text></ExampleBlock><ExampleBlock title="笔锋模式 + 历史记录"><Signature pressure enableHistory height={300} minWidth={1} maxWidth={6} backgroundColor="#f5f5f5" onConfirm={confirm}/><text className="demo-signature-tip">结合历史记录，支持笔锋效果的撤销与恢复</text></ExampleBlock></DemoGroup>
    <DemoGroup title="组件样式"><ExampleBlock title="自定义按钮"><Signature disabled={disabled} enableHistory step={3} onConfirm={confirm} renderFooter={actions=>disabled?<Button block label="开始签名" onTap={()=>{ 'background only';setDisabled(false);}}/>:<><Button size="small" variant="plain" label="撤回" onTap={actions.revoke} disabled={!actions.canUndo}/><Button size="small" variant="plain" label="恢复" onTap={actions.restore} disabled={!actions.canRedo}/><Button size="small" variant="plain" label="清除" onTap={actions.clear}/><Button size="small" label="确定" onTap={()=>{ 'background only';actions.confirm();}}/></>}/></ExampleBlock><ExampleBlock title="自定义画笔"><Signature penColor="#0083ff" lineWidth={4} onConfirm={confirm}/></ExampleBlock></DemoGroup>
    <DemoGroup title="特殊样式"><ExampleBlock title="弹窗中使用"><view className="demo-signature-button-row"><Button label="打开签名板" onTap={()=>{ 'background only';setShow(true);}}/></view></ExampleBlock><ExampleBlock title="横屏签名"><view className="demo-signature-button-row"><Button label="使用横屏签名" onTap={()=>{ 'background only';onOpen('signature-landscape');}}/></view></ExampleBlock></DemoGroup>
    <Popup show={show} onChange={setShow} rootPortal position="bottom" closable className="demo-signature-popup" onAfterEnter={()=>{ 'background only';void ref.current?.init();}}><Signature ref={ref} height={300} enableHistory pressure backgroundColor="#f5f5f5" onConfirm={confirm}/></Popup>
    <SignaturePreview src={image} onClose={()=>{ 'background only';setImage('');}}/><Toast {...toast.props}/>
